css:
:root {
  /* Colors */
  --color-linen-canvas: #f5f4f0;
  --color-paper-white: #ffffff;
  --color-jet-black: #000000;
  --color-onyx-tile: #0b0d0b;
  --color-forest-panel: #0d1b15;
  --color-carbon-ink: #1d1d1b;
  --color-graphite-caption: #000000b3;
  --color-ash-hairline: #00000033;
  --color-fog-rule: #dfdfdf33;
  --color-charcoal-glass: #090c0ad9;
  --color-mint-signal: #99ffcc;
  --color-moss-stroke: #5c997a;

  /* Typography — Font Families */
  --font-recoleta: "Recoleta", "Fraunces", "Young Serif", ui-serif, Georgia, Cambria, "Times New Roman", Times, serif;
  --font-lota-grotesque-alt: "Lota Grotes Que Alt", "Lota Grotesque Alt", "Hanken Grotesk", "Instrument Sans", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;

  /* Typography — Scale */
  --text-small: 11px;
  --leading-small: 1.3;
  --tracking-small: 0px;
  --text-caption: 12px;
  --leading-caption: 1;
  --tracking-caption: 0px;
  --text-body-sm: 14px;
  --leading-body-sm: 1.3;
  --tracking-body-sm: 0px;
  --text-body: 16px;
  --leading-body: 1.5;
  --tracking-body: 0px;
  --text-body-lg: 20px;
  --leading-body-lg: 1.5;
  --tracking-body-lg: 0px;
  --text-subheading: 24px;
  --leading-subheading: 1.5;
  --tracking-subheading: 0px;
  --text-heading-sm: 32px;
  --leading-heading-sm: 1.2;
  --tracking-heading-sm: 0px;
  --text-heading: 40px;
  --leading-heading: 1.2;
  --tracking-heading: 0px;
  --text-heading-lg: 64px;
  --leading-heading-lg: 1.12;
  --tracking-heading-lg: -1.28px;
  --text-display: 84px;
  --leading-display: 1.1;
  --tracking-display: -2px;
  --tracking-label: 2px;

  /* Typography — Weights */
  --font-weight-regular: 400;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;
  --font-weight-bold: 700;

  /* Spacing */
  --spacing-2: 2px;
  --spacing-4: 4px;
  --spacing-6: 6px;
  --spacing-8: 8px;
  --spacing-12: 12px;
  --spacing-16: 16px;
  --spacing-22: 22px;
  --spacing-24: 24px;
  --spacing-32: 32px;
  --spacing-40: 40px;
  --spacing-44: 44px;
  --spacing-64: 64px;
  --spacing-88: 88px;
  --spacing-108: 108px;
  --spacing-120: 120px;
  --spacing-128: 128px;

  /* Layout */
  --layout-max-width: 1280px;
  --layout-prose-width: 768px;
  --layout-section-gap: 128px;
  --layout-card-padding: 24px;
  --layout-element-gap: 12px;

  /* Border Radius */
  --radius-sm: 8px;
  --radius-md: 16px;
  --radius-lg: 24px;
  --radius-xl: 100px;
  --radius-full: 999px;

  /* Named Radii */
  --radius-cards: 16px;
  --radius-buttons: 24px;
  --radius-pills: 999px;
  --radius-tags: 999px;
  --radius-avatars: 50%;
  --radius-images: 100px;
  --radius-inner-tiles: 8px;
  --radius-small-elements: 8px;

  /* Shadows */
  --shadow-md: 0px 4px 24px 0px #00000022;

  /* Surfaces */
  --surface-linen-canvas: #f5f4f0;
  --surface-paper-white: #ffffff;
  --surface-jet-black: #000000;
  --surface-onyx-tile: #0b0d0b;
  --surface-forest-panel: #0d1b15;
}

